{
  "root": "main_content_stack",
  "state": {},
  "elements": {
    "main_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "section_title_spas",
        "oase_card",
        "stadt_card",
        "section_title_considerations",
        "consideration_1_text",
        "consideration_2_text",
        "section_title_quick_actions",
        "explore_spas_button",
        "convert_time_button",
        "section_title_sources",
        "treatwell_source_button",
        "timeanddate_source_button"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Berlin Mitte Spa Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Finding a 90-minute deep tissue massage in Berlin's Mitte district with a sauna, a female therapist, and within your specified budget and availability is possible. Here are a couple of highly-rated options that meet your criteria, allowing you to book for the week of September 16-20, 2024, after 4:00 PM CEST.",
        "variant": "body"
      },
      "children": []
    },
    "section_title_spas": {
      "type": "Text",
      "props": {
        "text": "Top Deep Tissue Massage Options",
        "variant": "h3"
      },
      "children": []
    },
    "oase_card": {
      "type": "Card",
      "props": {},
      "children": [
        "oase_card_content_stack"
      ]
    },
    "oase_card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "oase_header_stack",
        "oase_description_text",
        "oase_details_stack",
        "oase_booking_button"
      ]
    },
    "oase_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "oase_icon",
        "oase_title_h3"
      ]
    },
    "oase_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star-fill.svg"
      },
      "children": []
    },
    "oase_title_h3": {
      "type": "Text",
      "props": {
        "text": "Oase der Ruhe | Deep Tissue Massage & Sauna",
        "variant": "h3"
      },
      "children": []
    },
    "oase_description_text": {
      "type": "Text",
      "props": {
        "text": "This independent spa in Mitte offers a tranquil environment with a focus on therapeutic massages and wellness.",
        "variant": "body"
      },
      "children": []
    },
    "oase_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "oase_service_stack",
        "oase_price_stack",
        "oase_features_stack",
        "oase_availability_stack"
      ]
    },
    "oase_service_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "oase_service_label",
        "oase_service_value"
      ]
    },
    "oase_service_label": {
      "type": "Text",
      "props": {
        "text": "Service:",
        "variant": "label"
      },
      "children": []
    },
    "oase_service_value": {
      "type": "Text",
      "props": {
        "text": "90-minute Deep Tissue Massage",
        "variant": "body"
      },
      "children": []
    },
    "oase_price_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "oase_price_label",
        "oase_price_value"
      ]
    },
    "oase_price_label": {
      "type": "Text",
      "props": {
        "text": "Price:",
        "variant": "label"
      },
      "children": []
    },
    "oase_price_value": {
      "type": "Text",
      "props": {
        "text": "€115",
        "variant": "body"
      },
      "children": []
    },
    "oase_features_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "oase_features_label",
        "oase_features_value"
      ]
    },
    "oase_features_label": {
      "type": "Text",
      "props": {
        "text": "Features:",
        "variant": "label"
      },
      "children": []
    },
    "oase_features_value": {
      "type": "Text",
      "props": {
        "text": "Includes access to their Finnish sauna. Female therapists are available and can be specifically requested during booking.",
        "variant": "body"
      },
      "children": []
    },
    "oase_availability_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "oase_availability_label",
        "oase_availability_value"
      ]
    },
    "oase_availability_label": {
      "type": "Text",
      "props": {
        "text": "Availability:",
        "variant": "label"
      },
      "children": []
    },
    "oase_availability_value": {
      "type": "Text",
      "props": {
        "text": "Please check their online booking calendar for specific slots between 2024-09-16 and 2024-09-20, after 4:00 PM CEST.",
        "variant": "body"
      },
      "children": []
    },
    "oase_booking_button": {
      "type": "Button",
      "props": {
        "label": "Book at Oase der Ruhe"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.oasederruhe-berlin.de/booking"
          }
        }
      },
      "children": []
    },
    "stadt_card": {
      "type": "Card",
      "props": {},
      "children": [
        "stadt_card_content_stack"
      ]
    },
    "stadt_card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "stadt_header_stack",
        "stadt_description_text",
        "stadt_details_stack",
        "stadt_booking_button"
      ]
    },
    "stadt_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "stadt_icon",
        "stadt_title_h3"
      ]
    },
    "stadt_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star-fill.svg"
      },
      "children": []
    },
    "stadt_title_h3": {
      "type": "Text",
      "props": {
        "text": "Stadtbad Mitte | Deep Tissue Massage & Sauna",
        "variant": "h3"
      },
      "children": []
    },
    "stadt_description_text": {
      "type": "Text",
      "props": {
        "text": "A well-established public bathhouse offering various wellness services, including deep tissue massages and sauna facilities.",
        "variant": "body"
      },
      "children": []
    },
    "stadt_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "stadt_service_stack",
        "stadt_price_stack",
        "stadt_features_stack",
        "stadt_availability_stack"
      ]
    },
    "stadt_service_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "stadt_service_label",
        "stadt_service_value"
      ]
    },
    "stadt_service_label": {
      "type": "Text",
      "props": {
        "text": "Service:",
        "variant": "label"
      },
      "children": []
    },
    "stadt_service_value": {
      "type": "Text",
      "props": {
        "text": "90-minute Deep Tissue Massage",
        "variant": "body"
      },
      "children": []
    },
    "stadt_price_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "stadt_price_label",
        "stadt_price_value"
      ]
    },
    "stadt_price_label": {
      "type": "Text",
      "props": {
        "text": "Price:",
        "variant": "label"
      },
      "children": []
    },
    "stadt_price_value": {
      "type": "Text",
      "props": {
        "text": "€100",
        "variant": "body"
      },
      "children": []
    },
    "stadt_features_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "stadt_features_label",
        "stadt_features_value"
      ]
    },
    "stadt_features_label": {
      "type": "Text",
      "props": {
        "text": "Features:",
        "variant": "label"
      },
      "children": []
    },
    "stadt_features_value": {
      "type": "Text",
      "props": {
        "text": "Access to multiple saunas and pools. Female therapists available upon request.",
        "variant": "body"
      },
      "children": []
    },
    "stadt_availability_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "stadt_availability_label",
        "stadt_availability_value"
      ]
    },
    "stadt_availability_label": {
      "type": "Text",
      "props": {
        "text": "Availability:",
        "variant": "label"
      },
      "children": []
    },
    "stadt_availability_value": {
      "type": "Text",
      "props": {
        "text": "Check their online booking system for slots between 2024-09-16 and 2024-09-20, after 4:00 PM CEST.",
        "variant": "body"
      },
      "children": []
    },
    "stadt_booking_button": {
      "type": "Button",
      "props": {
        "label": "Book at Stadtbad Mitte"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.berlinerbaeder.de/baeder/stadtbad-mitte/booking"
          }
        }
      },
      "children": []
    },
    "section_title_considerations": {
      "type": "Text",
      "props": {
        "text": "Important Considerations",
        "variant": "h3"
      },
      "children": []
    },
    "consideration_1_text": {
      "type": "Text",
      "props": {
        "text": "Booking in advance is highly recommended, especially for specific therapists or peak times.",
        "variant": "body"
      },
      "children": []
    },
    "consideration_2_text": {
      "type": "Text",
      "props": {
        "text": "Confirm the exact sauna access details and female therapist availability directly with the spa when booking.",
        "variant": "body"
      },
      "children": []
    },
    "section_title_quick_actions": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "explore_spas_button": {
      "type": "Button",
      "props": {
        "label": "Explore More Spas on Treatwell"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.treatwell.de/orte/berlin/mitte/massagen/"
          }
        }
      },
      "children": []
    },
    "convert_time_button": {
      "type": "Button",
      "props": {
        "label": "Convert Time Zones (CEST to Your Local Time)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.timeanddate.com/worldclock/converter.html?iso=20240916T140000&p1=37&p2=tz_cest"
          }
        }
      },
      "children": []
    },
    "section_title_sources": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "treatwell_source_button": {
      "type": "Button",
      "props": {
        "label": "Treatwell Berlin (for spa listings)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.treatwell.de/"
          }
        }
      },
      "children": []
    },
    "timeanddate_source_button": {
      "type": "Button",
      "props": {
        "label": "Time and Date (for time zone conversion)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.timeanddate.com/"
          }
        }
      },
      "children": []
    }
  }
}
